import sys
from collections import deque, defaultdict

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, idx):
    if idx >= len(nodes) or nodes[idx] is None:
        return None
    root = Node(nodes[idx])
    root.left = build_tree(nodes, 2 * idx + 1)
    root.right = build_tree(nodes, 2 * idx + 2)
    return root

def find_path(root, target):
    path = []
    stack = [(root, [])]
    while stack:
        node, curr_path = stack.pop()
        if node is None:
            continue
        new_path = curr_path + [node]
        if node.data == target:
            return new_path
        stack.append((node.right, new_path))
        stack.append((node.left, new_path))
    return None

def ladoos(root, home, K):
    if not root:
        return 0

    # Build adjacency map for undirected tree traversal
    adj = defaultdict(list)

    def build_adj(node):
        if not node:
            return
        if node.left:
            adj[node.data].append(node.left.data)
            adj[node.left.data].append(node.data)
            build_adj(node.left)
        if node.right:
            adj[node.data].append(node.right.data)
            adj[node.right.data].append(node.data)
            build_adj(node.right)

    build_adj(root)

    # BFS from home node
    visited = set()
    queue = deque([(home, 0)])
    visited.add(home)
    total_ladoos = 0

    while queue:
        current_node, dist = queue.popleft()

        if dist <= K:
            total_ladoos += current_node
        else:
            break

        if dist < K:
            for neighbor in adj[current_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))

    return total_ladoos

# Reading input and building tree
input_data = sys.stdin.read().split()
if not input_data:
    sys.exit(0)

iterator = iter(input_data)
try:
    n = int(next(iterator))
    nodes_input = []
    for _ in range(n):
        val = next(iterator)
        if val == 'None':
            nodes_input.append(None)
        else:
            nodes_input.append(int(val))

    home = int(next(iterator))
    K = int(next(iterator))

    # Build tree from level order list
    root = build_tree(nodes_input, 0)

    result = ladoos(root, home, K)
    print(result)
except StopIteration:
    pass
